msg.liveCash = parseFloat(msg.payload);
if (isNaN(msg.liveCash)) {
    node.error('Paycheck ungated test: live sensor.monarch_assets_cash is not numeric (' + msg.payload + ')', msg);
    return null;
}
msg.ts = new Date(Date.now() - 24*3600*1000).toISOString();
return msg;

const hist = msg.payload;
let baseline = NaN;
if (Array.isArray(hist) && Array.isArray(hist[0])) {
    for (const s of hist[0]) {
        const v = parseFloat(s.state);
        if (!isNaN(v)) { baseline = v; break; }
    }
}
if (isNaN(baseline)) {
    node.error('Paycheck ungated test: no numeric 24h history for sensor.monarch_assets_cash', msg);
    return null;
}
msg.payload = String(msg.liveCash);
msg.data = { old_state: { state: String(baseline) } };
return msg;

const ungated = msg._ungated === true;
const newVal = parseFloat(msg.payload);
const oldVal = parseFloat(msg.data && msg.data.old_state && msg.data.old_state.state);
if (isNaN(newVal)) {
    if (ungated) node.error('Paycheck ungated test: sensor.monarch_assets_cash is not numeric (' + msg.payload + ')', msg);
    return null;
}

const delta = newVal - oldVal;
if (!ungated) {
    if (isNaN(oldVal)) return null;
    if (delta < 4000) return null;
}

// Pay windows: 1st +/- 4 days (27th-5th) and 15th +/- 4 days (11th-19th)
const day = new Date().getDate();
const inWindow = (day >= 27 || day <= 5) || (day >= 11 && day <= 19);

const fmt = n => '$' + Math.round(n).toLocaleString('en-US');
const windowText = inWindow ? ' — lines up with payday' : ' — outside normal pay window';

msg.payload = {
    title: ungated ? '🧪 REAL TEST: Paycheck Alert' : (msg._manualTest ? '🧪 TEST: ' : '') + (inWindow ? '💰 Likely Paycheck' : '💵 Large Cash Increase'),
    message: ungated
        ? 'Estimated paycheck (24h change): ' + (delta >= 0 ? '+' : '-') + fmt(Math.abs(delta)) + windowText
        : 'Estimated paycheck: ' + fmt(delta) + windowText,
    color: '#2E7D32',
    channel: 'Network Restored'
};
return msg;
